class Solution:
    def catchMaximumPeople(self, team: List[int], dist: int) -> int:
        its = [i for i, v in enumerate(team) if v == 1]
        nonits = [i for i, v in enumerate(team) if v == 0]
        match = {}

        def augment(j, seen):
            for t in range(len(its)):
                if t in seen or abs(its[t] - nonits[j]) > dist:
                    continue
                seen.add(t)
                if t not in match or augment(match[t], seen):
                    match[t] = j
                    return True
            return False

        ans = 0
        for j in range(len(nonits)):
            if augment(j, set()):
                ans += 1
        return ans

