class Solution {
public:
    int catchMaximumPeople(vector<int>& team, int dist) {
        vector<int> its, nonits;
        for (int i = 0; i < (int)team.size(); ++i)
            (team[i] ? its : nonits).push_back(i);
        int m = its.size();
        vector<int> matchTo(m, -1);
        function<bool(int, vector<char>&)> augment =
            [&](int j, vector<char>& seen) -> bool {
            for (int t = 0; t < m; ++t) {
                if (seen[t] || abs(its[t] - nonits[j]) > dist) continue;
                seen[t] = 1;
                if (matchTo[t] == -1 || augment(matchTo[t], seen)) {
                    matchTo[t] = j;
                    return true;
                }
            }
            return false;
        };
        int ans = 0;
        for (int j = 0; j < (int)nonits.size(); ++j) {
            vector<char> seen(m, 0);
            if (augment(j, seen)) ans++;
        }
        return ans;
    }
};

