class Solution {
    private int[] its, nonits, matchTo;
    private int dist;

    public int catchMaximumPeople(int[] team, int dist) {
        this.dist = dist;
        int a = 0, b = 0;
        its = new int[team.length];
        nonits = new int[team.length];
        for (int i = 0; i < team.length; ++i) {
            if (team[i] == 1) its[a++] = i;
            else nonits[b++] = i;
        }
        matchTo = new int[a];
        Arrays.fill(matchTo, -1);
        int ans = 0;
        for (int j = 0; j < b; ++j) {
            if (augment(j, new boolean[a])) ans++;
        }
        return ans;
    }

    private boolean augment(int j, boolean[] seen) {
        for (int t = 0; t < its.length; ++t) {
            if (seen[t] || Math.abs(its[t] - nonits[j]) > dist) continue;
            seen[t] = true;
            if (matchTo[t] == -1 || augment(matchTo[t], seen)) {
                matchTo[t] = j;
                return true;
            }
        }
        return false;
    }
};

