class Solution:
    def catchMaximumPeople(self, team: List[int], dist: int) -> int:
        nonit = [i for i, v in enumerate(team) if v == 0]
        p = ans = 0
        for i, v in enumerate(team):
            if v != 1:
                continue
            while p < len(nonit) and nonit[p] < i - dist:
                p += 1
            if p < len(nonit) and nonit[p] <= i + dist:
                ans += 1
                p += 1
        return ans

