class Solution {
    public int catchMaximumPeople(int[] team, int dist) {
        int cnt = 0;
        for (int v : team) if (v == 0) cnt++;
        int[] nonit = new int[cnt];
        for (int i = 0, j = 0; i < team.length; ++i)
            if (team[i] == 0) nonit[j++] = i;
        int p = 0, ans = 0;
        for (int i = 0; i < team.length; ++i) {
            if (team[i] != 1) continue;
            while (p < cnt && nonit[p] < i - dist) p++;
            if (p < cnt && nonit[p] <= i + dist) {
                ans++;
                p++;
            }
        }
        return ans;
    }
};

